import { clamp, createRng } from "./math";

export { createRng };

export const AP_WIDTH = 780;
export const AP_HEIGHT = 480;
export const CYCLE_DURATION_SECONDS = 12.0;

export const NA_ION_COUNT = 44;
export const K_ION_COUNT = 44;
export const SPARK_COUNT = 36;
export const FIXED_DT = 1 / 60;

export const RESTING_MV = -70;
export const THRESHOLD_MV = -55;
export const PEAK_MV = 30;
export const HYPERPOLARIZED_MV = -80;

export const MEMBRANE_BOX = {
  x: 16,
  y: 238,
  width: 488,
  height: 228,
} as const;

export const MEMBRANE_MID_Y = 352;
export const MEMBRANE_HALF_THICK = 14;
export const EXTRACELLULAR_TOP = 248;
export const EXTRACELLULAR_BOTTOM = MEMBRANE_MID_Y - MEMBRANE_HALF_THICK - 3;
export const INTRACELLULAR_TOP = MEMBRANE_MID_Y + MEMBRANE_HALF_THICK + 3;
export const INTRACELLULAR_BOTTOM = 456;
export const CHAMBER_LEFT = 26;
export const CHAMBER_RIGHT = 494;

export const NA_CHANNEL_X = [142, 298] as const;
export const K_CHANNEL_X = [220, 376] as const;

export type ActionPotentialPhase =
  "resting" | "depolarization" | "peak" | "repolarization" | "hyperpolarization" | "restored";

export type ChannelGateState = "closed" | "open" | "inactivated" | "closing";
export type ActionPotentialSpeed = 0.5 | 1 | 2;

export interface IonParticle {
  id: number;
  kind: "na" | "k";
  x: number;
  y: number;
  vx: number;
  vy: number;
  /** Target pore index (0 or 1) when crossing the membrane. */
  lane: 0 | 1;
}

export interface SparkParticle {
  id: number;
  angle: number;
  radiusOffset: number;
  speed: number;
  size: number;
}

export interface ActionPotentialTelemetry {
  phase: ActionPotentialPhase;
  voltageMv: number;
  naChannelState: ChannelGateState;
  kChannelState: ChannelGateState;
  naInsideCount: number;
  kOutsideCount: number;
  naTotal: number;
  kTotal: number;
  cycleTime: number;
  active: boolean;
  loop: boolean;
}

export interface ActionPotentialSimulation {
  ions: IonParticle[];
  sparks: SparkParticle[];
  cycleTime: number;
  phase: ActionPotentialPhase;
  voltageMv: number;
  naOpen: number;
  naInactivated: number;
  kOpen: number;
  impulseProgress: number;
  active: boolean;
  loop: boolean;
  elapsedSeconds: number;
  accumulator: number;
  rng: () => number;
}

const PHASE_TIMESTAMPS: Record<ActionPotentialPhase, number> = {
  resting: 0.75,
  depolarization: 3.05,
  peak: 4.45,
  repolarization: 6.3,
  hyperpolarization: 8.3,
  restored: 10.6,
};

const MAX_FRAME_DELTA = 0.05;

function smoothstep(t: number): number {
  const x = clamp(t, 0, 1);
  return x * x * (3 - 2 * x);
}

export function phaseOfCycleTime(cycleTime: number): ActionPotentialPhase {
  const t = clamp(cycleTime, 0, CYCLE_DURATION_SECONDS);
  if (t < 1.8) return "resting";
  if (t < 3.8) return "depolarization";
  if (t < 5.2) return "peak";
  if (t < 7.4) return "repolarization";
  if (t < 9.2) return "hyperpolarization";
  return "restored";
}

export function voltageAtCycleTime(cycleTime: number): number {
  const t = clamp(cycleTime, 0, CYCLE_DURATION_SECONDS);
  if (t < 1.8) {
    return RESTING_MV;
  }
  if (t < 2.3) {
    return RESTING_MV + 15 * smoothstep((t - 1.8) / 0.5);
  }
  if (t < 3.8) {
    return THRESHOLD_MV + 81 * smoothstep((t - 2.3) / 1.5);
  }
  if (t < 5.2) {
    const u = (t - 3.8) / 1.4;
    return 26 + 2 * smoothstep(u) + 3 * Math.sin(u * Math.PI);
  }
  if (t < 7.4) {
    return 28 - 98 * smoothstep((t - 5.2) / 2.2);
  }
  if (t < 9.2) {
    const u = (t - 7.4) / 1.8;
    return RESTING_MV - 4 * smoothstep(u) - 7.8 * Math.sin(u * Math.PI);
  }
  return -74 + 4 * smoothstep((t - 9.2) / 2.8);
}

function channelActivations(cycleTime: number): {
  naOpen: number;
  naInactivated: number;
  kOpen: number;
  impulseProgress: number;
} {
  const t = clamp(cycleTime, 0, CYCLE_DURATION_SECONDS);

  let naOpen = 0;
  if (t >= 1.85 && t < 2.45) {
    naOpen = smoothstep((t - 1.85) / 0.6);
  } else if (t >= 2.45 && t < 3.7) {
    naOpen = 1;
  } else if (t >= 3.7 && t < 4.25) {
    naOpen = 1 - smoothstep((t - 3.7) / 0.55);
  }

  let naInactivated = 0;
  if (t >= 3.7 && t < 4.25) {
    naInactivated = smoothstep((t - 3.7) / 0.55);
  } else if (t >= 4.25 && t < 7.15) {
    naInactivated = 1;
  } else if (t >= 7.15 && t < 8.1) {
    naInactivated = 1 - smoothstep((t - 7.15) / 0.95);
  }

  let kOpen = 0;
  if (t >= 4.8 && t < 5.55) {
    kOpen = smoothstep((t - 4.8) / 0.75);
  } else if (t >= 5.55 && t < 7.45) {
    kOpen = 1;
  } else if (t >= 7.45 && t < 9.3) {
    kOpen = 1 - smoothstep((t - 7.45) / 1.85);
  }

  let impulseProgress = 0;
  if (t >= 1.8) {
    impulseProgress = smoothstep((t - 1.8) / 9.2);
  }

  return { naOpen, naInactivated, kOpen, impulseProgress };
}

function syncCurveState(sim: ActionPotentialSimulation): void {
  sim.phase = phaseOfCycleTime(sim.cycleTime);
  sim.voltageMv = Math.round(voltageAtCycleTime(sim.cycleTime));
  const act = channelActivations(sim.cycleTime);
  sim.naOpen = act.naOpen;
  sim.naInactivated = act.naInactivated;
  sim.kOpen = act.kOpen;
  sim.impulseProgress = act.impulseProgress;
}

function populateIonsForPhase(sim: ActionPotentialSimulation, phase: ActionPotentialPhase): void {
  const { ions, rng } = sim;
  ions.length = 0;

  let naInsideTarget = 4;
  let kOutsideTarget = 4;

  if (phase === "depolarization") {
    naInsideTarget = 16;
    kOutsideTarget = 5;
  } else if (phase === "peak") {
    naInsideTarget = 22;
    kOutsideTarget = 7;
  } else if (phase === "repolarization") {
    naInsideTarget = 18;
    kOutsideTarget = 20;
  } else if (phase === "hyperpolarization") {
    naInsideTarget = 10;
    kOutsideTarget = 17;
  }

  for (let i = 0; i < NA_ION_COUNT; i += 1) {
    const inside = i < naInsideTarget;
    const lane: 0 | 1 = i % 2 === 0 ? 0 : 1;
    const poreX = NA_CHANNEL_X[lane];
    const inPoreStream =
      phase === "depolarization" && i >= naInsideTarget - 4 && i < naInsideTarget;

    const x = inPoreStream
      ? poreX + (rng() - 0.5) * 14
      : CHAMBER_LEFT + rng() * (CHAMBER_RIGHT - CHAMBER_LEFT);
    const y = inPoreStream
      ? MEMBRANE_MID_Y - 12 + rng() * 34
      : inside
        ? INTRACELLULAR_TOP + 6 + rng() * (INTRACELLULAR_BOTTOM - INTRACELLULAR_TOP - 12)
        : EXTRACELLULAR_TOP + 6 + rng() * (EXTRACELLULAR_BOTTOM - EXTRACELLULAR_TOP - 12);

    ions.push({
      id: i,
      kind: "na",
      x,
      y,
      vx: (rng() - 0.5) * 42,
      vy: inPoreStream ? 70 + rng() * 45 : (rng() - 0.5) * 42,
      lane,
    });
  }

  for (let i = 0; i < K_ION_COUNT; i += 1) {
    const outside = i < kOutsideTarget;
    const lane: 0 | 1 = i % 2 === 0 ? 0 : 1;
    const poreX = K_CHANNEL_X[lane];
    const inPoreStream =
      phase === "repolarization" && i >= kOutsideTarget - 4 && i < kOutsideTarget;

    const x = inPoreStream
      ? poreX + (rng() - 0.5) * 14
      : CHAMBER_LEFT + rng() * (CHAMBER_RIGHT - CHAMBER_LEFT);
    const y = inPoreStream
      ? MEMBRANE_MID_Y - 22 + rng() * 34
      : outside
        ? EXTRACELLULAR_TOP + 6 + rng() * (EXTRACELLULAR_BOTTOM - EXTRACELLULAR_TOP - 12)
        : INTRACELLULAR_TOP + 6 + rng() * (INTRACELLULAR_BOTTOM - INTRACELLULAR_TOP - 12);

    ions.push({
      id: NA_ION_COUNT + i,
      kind: "k",
      x,
      y,
      vx: (rng() - 0.5) * 42,
      vy: inPoreStream ? -(70 + rng() * 45) : (rng() - 0.5) * 42,
      lane,
    });
  }
}

function createSparks(rng: () => number): SparkParticle[] {
  const sparks: SparkParticle[] = [];
  for (let i = 0; i < SPARK_COUNT; i += 1) {
    sparks.push({
      id: i,
      angle: rng() * Math.PI * 2,
      radiusOffset: 10 + rng() * 28,
      speed: 1.6 + rng() * 2.8,
      size: 1.4 + rng() * 1.9,
    });
  }
  return sparks;
}

export function createActionPotentialSimulation(options?: {
  seed?: number;
  phase?: ActionPotentialPhase;
  loop?: boolean;
}): ActionPotentialSimulation {
  const seed = options?.seed ?? 20261124;
  const phase = options?.phase ?? "resting";
  const loop = options?.loop ?? true;
  const rng = createRng(seed);

  const sim: ActionPotentialSimulation = {
    ions: [],
    sparks: createSparks(rng),
    cycleTime: phase === "resting" ? 0 : PHASE_TIMESTAMPS[phase],
    phase,
    voltageMv: RESTING_MV,
    naOpen: 0,
    naInactivated: 0,
    kOpen: 0,
    impulseProgress: 0,
    active: phase !== "resting" || loop,
    loop,
    elapsedSeconds: 0,
    accumulator: 0,
    rng,
  };

  syncCurveState(sim);
  populateIonsForPhase(sim, phase);
  return sim;
}

export function triggerActionPotential(sim: ActionPotentialSimulation): void {
  sim.active = true;
  sim.cycleTime = 1.85;
  syncCurveState(sim);
  populateIonsForPhase(sim, "resting");
}

export function jumpToActionPotentialPhase(
  sim: ActionPotentialSimulation,
  phase: ActionPotentialPhase,
): void {
  sim.cycleTime = phase === "resting" ? 0.6 : PHASE_TIMESTAMPS[phase];
  sim.active = phase !== "resting" || sim.loop;
  syncCurveState(sim);
  populateIonsForPhase(sim, phase);
}

export function setActionPotentialLoop(sim: ActionPotentialSimulation, loop: boolean): void {
  sim.loop = loop;
  if (loop && !sim.active) {
    sim.active = true;
  }
}

function insideCount(ions: IonParticle[], kind: "na" | "k"): number {
  let count = 0;
  for (let i = 0; i < ions.length; i += 1) {
    const ion = ions[i]!;
    if (ion.kind === kind && ion.y >= MEMBRANE_MID_Y) count += 1;
  }
  return count;
}

function outsideCount(ions: IonParticle[], kind: "na" | "k"): number {
  let count = 0;
  for (let i = 0; i < ions.length; i += 1) {
    const ion = ions[i]!;
    if (ion.kind === kind && ion.y < MEMBRANE_MID_Y) count += 1;
  }
  return count;
}

function stepSubstep(sim: ActionPotentialSimulation, dt: number): void {
  const { ions, sparks, rng } = sim;

  if (sim.active) {
    sim.cycleTime += dt;
    if (sim.cycleTime >= CYCLE_DURATION_SECONDS) {
      if (sim.loop) {
        sim.cycleTime -= CYCLE_DURATION_SECONDS;
      } else {
        sim.cycleTime = 0;
        sim.active = false;
      }
    }
  }

  syncCurveState(sim);
  sim.elapsedSeconds += dt;

  for (let i = 0; i < sparks.length; i += 1) {
    const spark = sparks[i]!;
    spark.angle = (spark.angle + spark.speed * dt) % (Math.PI * 2);
  }

  const naFlowOpen = sim.naOpen > 0.28 && sim.naInactivated < 0.55;
  const kFlowOpen = sim.kOpen > 0.28;
  const pumpActive = sim.phase === "restored" || sim.phase === "resting";

  const naInside = insideCount(ions, "na");
  const kOutside = outsideCount(ions, "k");

  const damping = Math.pow(0.92, dt * 60);

  for (let i = 0; i < ions.length; i += 1) {
    const ion = ions[i]!;

    // Brownian thermal motion.
    ion.vx += (rng() - 0.5) * 320 * dt;
    ion.vy += (rng() - 0.5) * 320 * dt;

    if (ion.kind === "na") {
      const poreX = NA_CHANNEL_X[ion.lane];

      if (naFlowOpen && ion.y < MEMBRANE_MID_Y + 8 && naInside < 26) {
        // Funnel nearby extracellular Na+ smoothly downward through open Na+ pores.
        const dx = poreX - ion.x;
        if (Math.abs(dx) < 120 || ion.y > EXTRACELLULAR_BOTTOM - 26) {
          ion.vx += clamp(dx * 5.2, -160, 160) * dt;
          if (Math.abs(dx) < 14) {
            ion.vy += 290 * sim.naOpen * dt;
          } else {
            ion.vy += clamp((EXTRACELLULAR_BOTTOM - ion.y) * 2.2, -70, 120) * dt;
          }
        }
      } else if (pumpActive && ion.y > MEMBRANE_MID_Y && naInside > 5) {
        // Na+/K+ pump gradually restores Na+ outside during recovery.
        const dx = poreX - ion.x;
        ion.vx += clamp(dx * 2.6, -95, 95) * dt;
        if (Math.abs(dx) < 18) {
          ion.vy -= 210 * dt;
        }
      }
    } else {
      const poreX = K_CHANNEL_X[ion.lane];

      if (kFlowOpen && ion.y > MEMBRANE_MID_Y - 8 && kOutside < 26) {
        // Funnel intracellular K+ upward through open K+ pores.
        const dx = poreX - ion.x;
        if (Math.abs(dx) < 120 || ion.y < INTRACELLULAR_TOP + 26) {
          ion.vx += clamp(dx * 5.2, -160, 160) * dt;
          if (Math.abs(dx) < 14) {
            ion.vy -= 290 * sim.kOpen * dt;
          } else {
            ion.vy += clamp((INTRACELLULAR_TOP - ion.y) * 2.2, -120, 70) * dt;
          }
        }
      } else if (pumpActive && ion.y < MEMBRANE_MID_Y && kOutside > 5) {
        // Na+/K+ pump restores K+ inside during recovery.
        const dx = poreX - ion.x;
        ion.vx += clamp(dx * 2.6, -95, 95) * dt;
        if (Math.abs(dx) < 18) {
          ion.vy += 210 * dt;
        }
      }
    }

    ion.vx = clamp(ion.vx * damping, -220, 220);
    ion.vy = clamp(ion.vy * damping, -240, 240);

    const prevY = ion.y;
    ion.x += ion.vx * dt;
    ion.y += ion.vy * dt;

    // Outer chamber boundary reflections.
    if (ion.x < CHAMBER_LEFT) {
      ion.x = CHAMBER_LEFT;
      ion.vx = Math.abs(ion.vx) * 0.75;
    } else if (ion.x > CHAMBER_RIGHT) {
      ion.x = CHAMBER_RIGHT;
      ion.vx = -Math.abs(ion.vx) * 0.75;
    }

    if (ion.y < EXTRACELLULAR_TOP) {
      ion.y = EXTRACELLULAR_TOP;
      ion.vy = Math.abs(ion.vy) * 0.75;
    } else if (ion.y > INTRACELLULAR_BOTTOM) {
      ion.y = INTRACELLULAR_BOTTOM;
      ion.vy = -Math.abs(ion.vy) * 0.75;
    }

    // Selective membrane permeability: only allow crossing through matching open channel pores.
    const poreX = ion.kind === "na" ? NA_CHANNEL_X[ion.lane] : K_CHANNEL_X[ion.lane];
    const poreClearance = Math.abs(ion.x - poreX) < 11;
    const crossingAllowed =
      poreClearance && (ion.kind === "na" ? naFlowOpen || pumpActive : kFlowOpen || pumpActive);

    if (!crossingAllowed) {
      if (prevY <= EXTRACELLULAR_BOTTOM && ion.y > EXTRACELLULAR_BOTTOM) {
        ion.y = EXTRACELLULAR_BOTTOM;
        ion.vy = -Math.abs(ion.vy) * 0.75;
      } else if (prevY >= INTRACELLULAR_TOP && ion.y < INTRACELLULAR_TOP) {
        ion.y = INTRACELLULAR_TOP;
        ion.vy = Math.abs(ion.vy) * 0.75;
      } else if (ion.y > EXTRACELLULAR_BOTTOM && ion.y < INTRACELLULAR_TOP) {
        if (ion.y < MEMBRANE_MID_Y) {
          ion.y = EXTRACELLULAR_BOTTOM;
          ion.vy = -Math.abs(ion.vy) * 0.75;
        } else {
          ion.y = INTRACELLULAR_TOP;
          ion.vy = Math.abs(ion.vy) * 0.75;
        }
      }
    }
  }
}

export function stepActionPotentialSimulation(
  sim: ActionPotentialSimulation,
  elapsedSeconds: number,
  speed: ActionPotentialSpeed = 1,
): void {
  const clampedDelta = clamp(elapsedSeconds, 0, MAX_FRAME_DELTA);
  if (clampedDelta <= 0) return;

  sim.accumulator += clampedDelta * speed;
  while (sim.accumulator >= FIXED_DT) {
    stepSubstep(sim, FIXED_DT);
    sim.accumulator -= FIXED_DT;
  }
}

export function getActionPotentialTelemetry(
  sim: ActionPotentialSimulation,
): ActionPotentialTelemetry {
  const naChannelState: ChannelGateState =
    sim.naInactivated >= 0.45 ? "inactivated" : sim.naOpen >= 0.35 ? "open" : "closed";
  const kChannelState: ChannelGateState =
    sim.phase === "hyperpolarization" && sim.kOpen > 0.08
      ? "closing"
      : sim.kOpen >= 0.35
        ? "open"
        : "closed";

  return {
    phase: sim.phase,
    voltageMv: sim.voltageMv,
    naChannelState,
    kChannelState,
    naInsideCount: insideCount(sim.ions, "na"),
    kOutsideCount: outsideCount(sim.ions, "k"),
    naTotal: NA_ION_COUNT,
    kTotal: K_ION_COUNT,
    cycleTime: sim.cycleTime,
    active: sim.active,
    loop: sim.loop,
  };
}

/** Compare UI-visible action potential telemetry fields to avoid redundant React state updates. */
export function sameActionPotentialTelemetry(
  a: ActionPotentialTelemetry,
  b: ActionPotentialTelemetry,
): boolean {
  return (
    a.phase === b.phase &&
    a.voltageMv === b.voltageMv &&
    a.naChannelState === b.naChannelState &&
    a.kChannelState === b.kChannelState &&
    a.active === b.active &&
    a.loop === b.loop
  );
}
