import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { getSource, requireSpecimen } from "../content";
import { navigateToStructure } from "../lib/navigation";
import { useSlidingPill } from "../lib/use-sliding-pill";
import {
  AP_HEIGHT,
  AP_WIDTH,
  createActionPotentialSimulation,
  getActionPotentialTelemetry,
  jumpToActionPotentialPhase,
  sameActionPotentialTelemetry,
  setActionPotentialLoop,
  stepActionPotentialSimulation,
  triggerActionPotential,
  type ActionPotentialPhase,
  type ActionPotentialSimulation,
  type ActionPotentialSpeed,
  type ActionPotentialTelemetry,
} from "../sim/action-potential-engine";
import { renderActionPotentialFrame } from "../sim/action-potential-renderer";
import { IconArrowUpRight, IconBolt, IconLoop, IconPause, IconPlay } from "../components/Icons";

const PHASE_LABELS: Record<ActionPotentialPhase, string> = {
  resting: "Resting",
  depolarization: "Depolarization",
  peak: "Signal peak",
  repolarization: "Repolarization",
  hyperpolarization: "Hyperpolarization",
  restored: "Restored",
};

const STAGES: Array<{ id: ActionPotentialPhase; label: string }> = [
  { id: "resting", label: "Resting" },
  { id: "depolarization", label: "Depolarization" },
  { id: "peak", label: "Peak" },
  { id: "repolarization", label: "Repolarization" },
  { id: "hyperpolarization", label: "Hyperpolarization" },
  { id: "restored", label: "Restored" },
];

const SPEEDS: Array<{ value: ActionPotentialSpeed; label: string }> = [
  { value: 0.5, label: "0.5×" },
  { value: 1, label: "1×" },
  { value: 2, label: "2×" },
];

const EXPLANATIONS: Record<ActionPotentialPhase, { badge: string; heading: string; body: string }> =
  {
    resting: {
      badge: "Resting potential",
      heading: "Neuron polarized at −70 mV",
      body: "Before an impulse starts, voltage-gated Na⁺ and K⁺ channels are closed. The Na⁺/K⁺ pump maintains high extracellular Na⁺ (+ outside) and high intracellular K⁺ (− inside) across the axon membrane.",
    },
    depolarization: {
      badge: "Depolarization",
      heading: "Na⁺ enters rapidly after threshold (−55 mV)",
      body: "Once a stimulus crosses threshold (−55 mV), voltage-gated Na⁺ channels snap open and positively charged Na⁺ rushes into the axon, flipping local polarity and driving membrane voltage upward.",
    },
    peak: {
      badge: "Action potential",
      heading: "Signal peak reaches +30 mV",
      body: "Membrane potential crests around +30 mV as the electric wave leaps between nodes of Ranvier. Na⁺ channels quickly inactivate via their cytoplasmic gate while voltage-gated K⁺ channels begin opening.",
    },
    repolarization: {
      badge: "Repolarization",
      heading: "K⁺ leaves to restore negative charge",
      body: "Voltage-gated K⁺ channels open wide and K⁺ ions flow out into the extracellular fluid, pulling membrane potential steeply back down toward −70 mV as the impulse advances down the axon.",
    },
    hyperpolarization: {
      badge: "Hyperpolarization",
      heading: "Temporarily more negative (−80 mV)",
      body: "Because voltage-gated K⁺ channels close slowly, extra K⁺ continues leaving briefly, dipping the membrane below rest (~−80 mV) during the refractory period while Na⁺ channels reset.",
    },
    restored: {
      badge: "Resting restored",
      heading: "Resting state restored as signal moves forward",
      body: "K⁺ channels finish closing and membrane potential settles back to −70 mV while the action potential sweeps onward to the axon terminals to trigger neurotransmitter release.",
    },
  };

const NEURON_STRUCTURE_IDS = [
  "soma",
  "dendrite",
  "axon",
  "myelin-sheath",
  "axon-terminal",
  "mitochondrion",
] as const;

function formatVoltage(mv: number): string {
  return mv > 0 ? `+${mv} mV` : `${mv} mV`;
}

export function ActionPotentialSimulator({ reduceMotion }: { reduceMotion: boolean }) {
  const initialPhase: ActionPotentialPhase = reduceMotion ? "depolarization" : "resting";
  const [speed, setSpeed] = useState<ActionPotentialSpeed>(1);
  const [running, setRunning] = useState<boolean>(() => !reduceMotion);
  const [loop, setLoop] = useState<boolean>(true);
  const [showExplanations, setShowExplanations] = useState<boolean>(true);

  const simRef = useRef<ActionPotentialSimulation | null>(null);
  if (!simRef.current) {
    simRef.current = createActionPotentialSimulation({
      seed: 20261124,
      phase: initialPhase,
      loop: true,
    });
  }

  const [telemetry, setTelemetry] = useState<ActionPotentialTelemetry>(() =>
    getActionPotentialTelemetry(simRef.current!),
  );
  const syncTelemetry = useCallback((sim: ActionPotentialSimulation) => {
    const next = getActionPotentialTelemetry(sim);
    setTelemetry((prev) => (sameActionPotentialTelemetry(prev, next) ? prev : next));
  }, []);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const sizeRef = useRef<{ width: number; height: number; dpr: number }>({
    width: AP_WIDTH,
    height: AP_HEIGHT,
    dpr: 1,
  });

  const speedRef = useRef<ActionPotentialSpeed>(speed);
  speedRef.current = speed;
  const runningRef = useRef<boolean>(running);
  runningRef.current = running;

  const speedIndex = Math.max(
    0,
    SPEEDS.findIndex((entry) => entry.value === speed),
  );
  const speedPill = useSlidingPill<HTMLButtonElement>(speedIndex, reduceMotion);

  const neuronSpecimen = useMemo(() => requireSpecimen("neuron"), []);
  const neuronStructures = useMemo(
    () =>
      NEURON_STRUCTURE_IDS.flatMap((id) => {
        const found = neuronSpecimen.structures.find((structure) => structure.id === id);
        return found ? [found] : [];
      }),
    [neuronSpecimen],
  );
  const openStax351 = getSource("openstax-bio-35-1");
  const openStax352 = getSource("openstax-bio-35-2");

  const drawFrame = useCallback(() => {
    const canvas = canvasRef.current;
    const sim = simRef.current;
    if (!canvas || !sim) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const { width, height, dpr } = sizeRef.current;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    renderActionPotentialFrame(ctx, sim, width, height);
  }, []);

  const syncCanvasDimensions = useCallback(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;

    const rect = stage.getBoundingClientRect();
    const width = Math.max(240, Math.round(rect.width));
    const height = Math.max(150, Math.round(rect.height));
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    sizeRef.current = { width, height, dpr };
    const targetW = Math.round(width * dpr);
    const targetH = Math.round(height * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    drawFrame();
  }, [drawFrame]);

  useEffect(() => {
    syncCanvasDimensions();
    const stage = stageRef.current;
    if (!stage || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => syncCanvasDimensions());
    observer.observe(stage);
    return () => observer.disconnect();
  }, [syncCanvasDimensions]);

  useEffect(() => {
    if (reduceMotion) {
      setRunning(false);
    }
  }, [reduceMotion]);

  useEffect(() => {
    if (!running) {
      drawFrame();
      return;
    }

    let rafId = 0;
    let lastTime = performance.now();
    let lastTelemetryPush = lastTime;

    const tick = (now: number) => {
      if (!runningRef.current) return;
      const dt = Math.max(0, (now - lastTime) / 1000);
      lastTime = now;

      const sim = simRef.current;
      if (sim && !document.hidden) {
        stepActionPotentialSimulation(sim, dt, speedRef.current);
        drawFrame();

        if (now - lastTelemetryPush >= 85) {
          lastTelemetryPush = now;
          syncTelemetry(sim);
        }
      }
      rafId = requestAnimationFrame(tick);
    };

    const handleVisibility = () => {
      lastTime = performance.now();
    };
    document.addEventListener("visibilitychange", handleVisibility);
    rafId = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(rafId);
      document.removeEventListener("visibilitychange", handleVisibility);
    };
  }, [running, drawFrame, syncTelemetry]);

  const handleFireImpulse = () => {
    const sim = simRef.current;
    if (!sim) return;
    triggerActionPotential(sim);
    syncTelemetry(sim);
    if (!running && !reduceMotion) {
      setRunning(true);
    }
    drawFrame();
  };

  const handleToggleLoop = () => {
    const sim = simRef.current;
    if (!sim) return;
    const nextLoop = !loop;
    setLoop(nextLoop);
    setActionPotentialLoop(sim, nextLoop);
    syncTelemetry(sim);
  };

  const handleJumpStage = (phase: ActionPotentialPhase) => {
    const sim = simRef.current;
    if (!sim) return;
    jumpToActionPotentialPhase(sim, phase);
    syncTelemetry(sim);
    drawFrame();
  };

  const handleStep = () => {
    const sim = simRef.current;
    if (!sim) return;
    if (!sim.active) {
      triggerActionPotential(sim);
    }
    stepActionPotentialSimulation(sim, 0.2, speed);
    syncTelemetry(sim);
    drawFrame();
  };

  const handleCanvasPointerDown = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (event.button !== 0 && event.pointerType === "mouse") return;
    handleFireImpulse();
  };

  const explanation = EXPLANATIONS[telemetry.phase];

  return (
    <>
      <section className="lab-card" aria-label="Action potential simulator">
        <div className="lab-toolbar">
          <div
            className="segmented"
            role="group"
            aria-label="Simulation speed"
            ref={speedPill.containerRef}
          >
            <span className="spring-pill" aria-hidden="true" ref={speedPill.pillRef} />
            {SPEEDS.map((entry, index) => (
              <button
                key={entry.label}
                ref={speedPill.registerItem(index)}
                type="button"
                aria-pressed={speed === entry.value}
                onClick={() => setSpeed(entry.value)}
              >
                {entry.label}
              </button>
            ))}
          </div>

          <button type="button" className="button button--primary" onClick={handleFireImpulse}>
            <IconBolt />
            <span>Fire impulse</span>
          </button>

          <button
            type="button"
            className="button button--ghost"
            aria-pressed={running}
            onClick={() => setRunning((prev) => !prev)}
          >
            {running ? <IconPause /> : <IconPlay />}
            <span>{running ? "Pause" : "Play"}</span>
          </button>

          {!running && (
            <button type="button" className="button button--ghost" onClick={handleStep}>
              Step
            </button>
          )}

          <button
            type="button"
            className="button button--ghost"
            aria-pressed={loop}
            onClick={handleToggleLoop}
          >
            <IconLoop />
            <span>Loop</span>
          </button>

          <button
            type="button"
            role="switch"
            aria-checked={showExplanations}
            className="lab-switch"
            onClick={() => setShowExplanations((prev) => !prev)}
          >
            <span className="lab-switch__label">Explanations</span>
            <span className="lab-switch__track" aria-hidden="true">
              <span className="lab-switch__thumb" />
            </span>
          </button>
        </div>

        <div className="lab-telemetry">
          <div className="lab-metric">
            <span className="lab-metric__label">Membrane potential</span>
            <strong className="lab-metric__value">{formatVoltage(telemetry.voltageMv)}</strong>
            <span className="lab-metric__note">resting: −70 mV · threshold: −55 mV</span>
          </div>

          <div className="lab-metric lab-metric--right">
            <span className="lab-metric__label">Current phase</span>
            <strong className={`lab-metric__value ap-status ap-status--${telemetry.phase}`}>
              {PHASE_LABELS[telemetry.phase]}
            </strong>
            <span className="lab-metric__note">
              Na⁺ channels: <strong>{telemetry.naChannelState}</strong> · K⁺ channels:{" "}
              <strong>{telemetry.kChannelState}</strong>
            </span>
          </div>
        </div>

        <div className="ap-stage-row">
          <span className="lab-start-row__label">stage</span>
          <div className="ap-stage-pills" role="group" aria-label="Action potential stages">
            {STAGES.map((stage) => (
              <button
                key={stage.id}
                type="button"
                className="chip"
                aria-pressed={telemetry.phase === stage.id}
                onClick={() => handleJumpStage(stage.id)}
              >
                {stage.label}
              </button>
            ))}
          </div>
        </div>

        <div className="ap-stage" ref={stageRef}>
          <canvas
            ref={canvasRef}
            className="lab-canvas"
            aria-hidden="true"
            title="Tap or click to fire an action potential impulse"
            onPointerDown={handleCanvasPointerDown}
          />
          <p className="visually-hidden" aria-live="polite">
            Phase: {PHASE_LABELS[telemetry.phase]}. Membrane potential{" "}
            {formatVoltage(telemetry.voltageMv)}. Sodium channels {telemetry.naChannelState};
            potassium channels {telemetry.kChannelState}.
          </p>
        </div>

        {reduceMotion && !running && (
          <p className="lab-motion-note muted small">
            Reduced motion is active, so the simulation starts paused. Use <strong>Play</strong>,{" "}
            <strong>Step</strong>, <strong>Fire impulse</strong>, or any <strong>stage</strong>{" "}
            button to inspect each step at your own pace.
          </p>
        )}

        {showExplanations && (
          <article className="lab-explain" aria-live="polite">
            <div className="lab-explain__head">
              <span className={`lab-explain__badge ap-badge--${telemetry.phase}`}>
                {explanation.badge}
              </span>
              <h2>{explanation.heading}</h2>
            </div>
            <p>{explanation.body}</p>
          </article>
        )}
      </section>

      <div className="lab-info-grid">
        <section className="panel" aria-labelledby="ap-key-heading">
          <p className="eyebrow">Visual key</p>
          <h2 id="ap-key-heading">Reading the nerve impulse</h2>
          <ul className="lab-legend">
            <li>
              <span className="lab-swatch lab-swatch--na" aria-hidden="true" />
              <div>
                <strong>Sodium ions (Na⁺ · 44 total)</strong>
                <span className="muted small">
                  Concentrated outside at rest; enter rapidly through open Na⁺ channels during
                  depolarization.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--k" aria-hidden="true" />
              <div>
                <strong>Potassium ions (K⁺ · 44 total)</strong>
                <span className="muted small">
                  Concentrated inside axoplasm; exit through delayed K⁺ channels to repolarize the
                  membrane.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--impulse" aria-hidden="true" />
              <div>
                <strong>Saltatory electric impulse</strong>
                <span className="muted small">
                  Leaps between myelin gaps (nodes of Ranvier) as Na⁺ influx triggers neighboring
                  channels.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--recovery" aria-hidden="true" />
              <div>
                <strong>Recovery wave to terminals</strong>
                <span className="muted small">
                  Warm amber wave tracks resting potential recovery while the signal reaches
                  synaptic boutons.
                </span>
              </div>
            </li>
          </ul>
          <p className="muted small">
            Schematic physiological model: ion counts (44 Na⁺, 44 K⁺), cycle duration (12 s), and
            axon length are compressed for clarity rather than real millisecond timing.
          </p>
        </section>

        <section className="panel" aria-labelledby="ap-neuron-heading">
          <p className="eyebrow">Gallery &amp; references</p>
          <h2 id="ap-neuron-heading">Inspect the 3D Neuron &amp; sources</h2>
          <p className="muted small">
            Jump directly to any mapped structure on the 3D multipolar neuron model, or consult the
            OpenStax chapters supporting these mechanisms.
          </p>
          <div className="lab-specimen-links">
            {neuronStructures.map((structure) => (
              <button
                key={structure.id}
                type="button"
                className="chip"
                onClick={() => navigateToStructure("neuron", structure.id)}
              >
                <span
                  className="specimen-dot"
                  style={{ "--dot-accent": neuronSpecimen.accent } as CSSProperties}
                  aria-hidden="true"
                />
                <span>{structure.name}</span>
              </button>
            ))}
          </div>
          <ul className="source-list">
            {openStax351 && (
              <li>
                <a href={openStax351.url} target="_blank" rel="noreferrer noopener">
                  <span>{openStax351.title}</span>
                  <IconArrowUpRight />
                </a>
                <span className="muted small">
                  {openStax351.publisher} · {openStax351.edition} · neuron &amp; myelin anatomy
                </span>
              </li>
            )}
            {openStax352 && (
              <li>
                <a href={openStax352.url} target="_blank" rel="noreferrer noopener">
                  <span>{openStax352.title}</span>
                  <IconArrowUpRight />
                </a>
                <span className="muted small">
                  {openStax352.publisher} · {openStax352.edition} · resting &amp; action potentials
                </span>
              </li>
            )}
          </ul>
        </section>
      </div>
    </>
  );
}
