function drawRoundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, r);
}

type BackgroundCache = {
  canvas: HTMLCanvasElement;
  width: number;
  height: number;
};

type IonSprite = {
  canvas: HTMLCanvasElement;
  logicalSize: number;
  halfSize: number;
};

const ION_SPRITE_SCALE = 3;
let backgroundCache: BackgroundCache | null = null;
let naSpriteCache: IonSprite | null = null;
let kSpriteCache: IonSprite | null = null;

function paintCachedBackground(
  ctx: CanvasRenderingContext2D,
  targetWidth: number,
  targetHeight: number,
): boolean {
  if (typeof document === "undefined") return false;
  if (
    !backgroundCache ||
    backgroundCache.width !== targetWidth ||
    backgroundCache.height !== targetHeight
  ) {
    const canvas = backgroundCache?.canvas ?? document.createElement("canvas");
    canvas.width = targetWidth;
    canvas.height = targetHeight;
    const bgCtx = canvas.getContext("2d");
    if (!bgCtx) return false;
    bgCtx.setTransform(targetWidth / AP_WIDTH, 0, 0, targetHeight / AP_HEIGHT, 0, 0);
    drawBackground(bgCtx);
    backgroundCache = { canvas, width: targetWidth, height: targetHeight };
  }
  ctx.drawImage(backgroundCache.canvas, 0, 0, AP_WIDTH, AP_HEIGHT);
  return true;
}

function createIonSprite(
  radius: number,
  stops: readonly [string, string, string],
): IonSprite | null {
  if (typeof document === "undefined") return null;
  const logicalSize = Math.ceil(radius * 2) + 2;
  const halfSize = logicalSize / 2;
  const canvas = document.createElement("canvas");
  canvas.width = logicalSize * ION_SPRITE_SCALE;
  canvas.height = logicalSize * ION_SPRITE_SCALE;
  const sctx = canvas.getContext("2d");
  if (!sctx) return null;
  sctx.setTransform(ION_SPRITE_SCALE, 0, 0, ION_SPRITE_SCALE, 0, 0);
  const grad = sctx.createRadialGradient(
    halfSize - 1.3,
    halfSize - 1.3,
    0.5,
    halfSize,
    halfSize,
    radius,
  );
  grad.addColorStop(0, stops[0]);
  grad.addColorStop(0.55, stops[1]);
  grad.addColorStop(1, stops[2]);
  sctx.fillStyle = grad;
  sctx.beginPath();
  sctx.arc(halfSize, halfSize, radius, 0, Math.PI * 2);
  sctx.fill();
  return { canvas, logicalSize, halfSize };
}

function getIonSprite(isNa: boolean): IonSprite | null {
  if (isNa) {
    if (!naSpriteCache) {
      naSpriteCache = createIonSprite(4.3, ["#fff8cf", "#ffd54f", "#cc8414"]);
    }
    return naSpriteCache;
  }
  if (!kSpriteCache) {
    kSpriteCache = createIonSprite(4.1, ["#f2fdff", "#83e2ff", "#2a8bc7"]);
  }
  return kSpriteCache;
}

function drawBackground(ctx: CanvasRenderingContext2D): void {
  const bg = ctx.createRadialGradient(340, 120, 40, 390, 240, 560);
  bg.addColorStop(0, "#102a4c");
  bg.addColorStop(0.55, "#091930");
  bg.addColorStop(1, "#050d1b");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, AP_WIDTH, AP_HEIGHT);

  // Subtle out-of-focus background neurons for neural microscopy depth.
  const ghosts = [
    { x: 645, y: 58, scale: 0.72 },
    { x: 35, y: 190, scale: 0.65 },
    { x: 735, y: 195, scale: 0.58 },
  ];
  ctx.save();
  for (const g of ghosts) {
    ctx.globalAlpha = 0.14;
    ctx.strokeStyle = "#5aa4e6";
    ctx.lineWidth = 2.2 * g.scale;
    const branches = [
      [-46, -26],
      [38, -32],
      [-52, 22],
      [44, 30],
      [6, -48],
    ];
    for (const [dx, dy] of branches) {
      ctx.beginPath();
      ctx.moveTo(g.x, g.y);
      ctx.quadraticCurveTo(
        g.x + dx! * 0.45 * g.scale,
        g.y + dy! * 0.75 * g.scale,
        g.x + dx! * g.scale,
        g.y + dy! * g.scale,
      );
      ctx.stroke();
    }
    const sg = ctx.createRadialGradient(g.x, g.y, 1, g.x, g.y, 20 * g.scale);
    sg.addColorStop(0, "#8ed3ff");
    sg.addColorStop(1, "rgba(90, 164, 230, 0)");
    ctx.fillStyle = sg;
    ctx.beginPath();
    ctx.arc(g.x, g.y, 20 * g.scale, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawLightningSegment(
  ctx: CanvasRenderingContext2D,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  seed: number,
  color: string,
  width: number,
): void {
  const steps = 10;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  for (let i = 1; i < steps; i += 1) {
    const t = i / steps;
    const bx = x1 + (x2 - x1) * t;
    const jitter = Math.sin(seed * 9.7 + i * 3.1) * 7.5;
    ctx.lineTo(bx, y1 + (y2 - y1) * t + jitter);
  }
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

function drawWholeNeuronScene(ctx: CanvasRenderingContext2D, sim: ActionPotentialSimulation): void {
  const somaX = 114;
  const somaY = 128;
  const axonStartX = 152;
  const axonEndX = 636;
  const axonY = 128;

  const mySegments = [
    { x: 164, w: 92 },
    { x: 280, w: 92 },
    { x: 396, w: 92 },
    { x: 512, w: 92 },
  ];
  const nodeCenters = [268, 384, 500];

  const waveActive = sim.impulseProgress > 0.01 && sim.impulseProgress < 0.99;
  const waveX = 132 + sim.impulseProgress * (736 - 132);
  const recoveryMode = sim.phase === "hyperpolarization" || sim.phase === "restored";
  const terminalGlow = sim.phase === "restored" ? Math.min(1, (sim.cycleTime - 9.2) / 1.4) : 0;

  // 1. Dendrite branches from soma.
  const dendrites: Array<[[number, number], [number, number], [number, number]]> = [
    [
      [somaX - 18, somaY - 12],
      [68, 86],
      [42, 62],
    ],
    [
      [68, 86],
      [52, 92],
      [32, 96],
    ],
    [
      [somaX - 20, somaY + 4],
      [62, 132],
      [32, 138],
    ],
    [
      [somaX - 14, somaY + 18],
      [68, 170],
      [44, 198],
    ],
    [
      [68, 170],
      [86, 186],
      [84, 212],
    ],
    [
      [somaX + 2, somaY - 22],
      [116, 82],
      [122, 54],
    ],
    [
      [somaX + 12, somaY + 20],
      [124, 174],
      [134, 204],
    ],
  ];

  ctx.save();
  ctx.lineCap = "round";
  for (const [p0, ctrl, p1] of dendrites) {
    ctx.strokeStyle = "rgba(86, 176, 255, 0.25)";
    ctx.lineWidth = 7.5;
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.quadraticCurveTo(ctrl[0], ctrl[1], p1[0], p1[1]);
    ctx.stroke();

    ctx.strokeStyle = "rgba(155, 218, 255, 0.72)";
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.quadraticCurveTo(ctrl[0], ctrl[1], p1[0], p1[1]);
    ctx.stroke();
  }

  // 2. Translucent glowing soma & axon hillock.
  const somaGlowBoost =
    sim.phase === "depolarization" && sim.cycleTime < 2.6
      ? Math.max(0, 1 - (sim.cycleTime - 1.85) / 0.75)
      : 0;

  const somaAura = ctx.createRadialGradient(somaX, somaY, 8, somaX, somaY, 54);
  somaAura.addColorStop(
    0,
    somaGlowBoost > 0.1
      ? `rgba(190, 244, 255, ${0.42 + somaGlowBoost * 0.4})`
      : "rgba(96, 186, 255, 0.38)",
  );
  somaAura.addColorStop(1, "rgba(38, 108, 194, 0)");
  ctx.fillStyle = somaAura;
  ctx.beginPath();
  ctx.arc(somaX, somaY, 54, 0, Math.PI * 2);
  ctx.fill();

  // Hillock taper into axon.
  ctx.fillStyle = "rgba(96, 184, 255, 0.26)";
  ctx.strokeStyle = "rgba(154, 218, 255, 0.75)";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(somaX + 18, somaY - 22);
  ctx.quadraticCurveTo(somaX + 34, somaY - 8, axonStartX, axonY - 7);
  ctx.lineTo(axonStartX, axonY + 7);
  ctx.quadraticCurveTo(somaX + 34, somaY + 8, somaX + 18, somaY + 22);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // Soma cell body membrane.
  const somaFill = ctx.createRadialGradient(somaX - 6, somaY - 6, 4, somaX, somaY, 32);
  somaFill.addColorStop(0, "rgba(182, 232, 255, 0.65)");
  somaFill.addColorStop(0.55, "rgba(74, 152, 232, 0.42)");
  somaFill.addColorStop(1, "rgba(42, 106, 186, 0.55)");
  ctx.fillStyle = somaFill;
  ctx.strokeStyle = "rgba(170, 224, 255, 0.86)";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(somaX, somaY, 29, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  // Soma nucleus.
  const nucGrad = ctx.createRadialGradient(somaX - 3, somaY - 3, 2, somaX, somaY, 13);
  nucGrad.addColorStop(0, "#d8f0ff");
  nucGrad.addColorStop(0.5, "#6eb7f5");
  nucGrad.addColorStop(1, "#3566ab");
  ctx.fillStyle = nucGrad;
  ctx.beginPath();
  ctx.arc(somaX, somaY, 12.5, 0, Math.PI * 2);
  ctx.fill();

  // 3. Axon core shaft.
  ctx.fillStyle = "rgba(86, 168, 245, 0.22)";
  ctx.fillRect(axonStartX, axonY - 7, axonEndX - axonStartX, 14);
  ctx.strokeStyle = "rgba(148, 212, 255, 0.68)";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(axonStartX, axonY - 7);
  ctx.lineTo(axonEndX, axonY - 7);
  ctx.moveTo(axonStartX, axonY + 7);
  ctx.lineTo(axonEndX, axonY + 7);
  ctx.stroke();

  // 4. Axon terminal arbor & synaptic boutons.
  const terminals: Array<{ ctrl: [number, number]; end: [number, number]; r: number }> = [
    { ctrl: [672, 92], end: [722, 74], r: 7 },
    { ctrl: [676, 112], end: [738, 106], r: 7 },
    { ctrl: [676, 142], end: [736, 148], r: 6.5 },
    { ctrl: [672, 166], end: [718, 184], r: 7 },
  ];
  for (const term of terminals) {
    ctx.strokeStyle =
      terminalGlow > 0.15
        ? `rgba(255, 222, 125, ${0.48 + terminalGlow * 0.5})`
        : "rgba(136, 206, 255, 0.65)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(axonEndX, axonY);
    ctx.quadraticCurveTo(term.ctrl[0], term.ctrl[1], term.end[0], term.end[1]);
    ctx.stroke();

    if (terminalGlow > 0.08) {
      const bg = ctx.createRadialGradient(
        term.end[0],
        term.end[1],
        1,
        term.end[0],
        term.end[1],
        20,
      );
      bg.addColorStop(0, `rgba(255, 236, 156, ${0.8 * terminalGlow})`);
      bg.addColorStop(1, "rgba(255, 210, 96, 0)");
      ctx.fillStyle = bg;
      ctx.beginPath();
      ctx.arc(term.end[0], term.end[1], 20, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = terminalGlow > 0.25 ? "#ffe38e" : "rgba(130, 204, 255, 0.72)";
    ctx.strokeStyle = terminalGlow > 0.25 ? "#fff7d1" : "rgba(196, 234, 255, 0.9)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(term.end[0], term.end[1], term.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  // 5. Myelin internodes (translucent glassy sleeves) leaving exposed Nodes of Ranvier.
  for (const seg of mySegments) {
    const grad = ctx.createLinearGradient(seg.x, axonY - 17, seg.x, axonY + 17);
    grad.addColorStop(0, "rgba(174, 224, 255, 0.45)");
    grad.addColorStop(0.38, "rgba(92, 166, 238, 0.24)");
    grad.addColorStop(0.75, "rgba(44, 108, 186, 0.36)");
    grad.addColorStop(1, "rgba(132, 200, 255, 0.35)");
    ctx.fillStyle = grad;
    ctx.strokeStyle = "rgba(160, 220, 255, 0.65)";
    ctx.lineWidth = 1.3;
    drawRoundRect(ctx, seg.x, axonY - 16, seg.w, 32, 11);
    ctx.fill();
    ctx.stroke();

    // Specular highlight along top of myelin capsule.
    ctx.strokeStyle = "rgba(224, 246, 255, 0.4)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(seg.x + 10, axonY - 11);
    ctx.lineTo(seg.x + seg.w - 10, axonY - 11);
    ctx.stroke();
  }

  // 6. Axon surface polarity (+ outside, - inside) flipping as wave passes.
  ctx.font = '600 10px ui-monospace, "SF Mono", Menlo, monospace';
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  for (let x = 160; x <= 620; x += 28) {
    const depolarizedHere = waveActive && Math.abs(x - waveX) < 58 && !recoveryMode;
    ctx.fillStyle = depolarizedHere ? "#ffdf78" : "rgba(164, 216, 255, 0.72)";
    ctx.fillText(depolarizedHere ? "−" : "+", x, axonY - 23);
    ctx.fillStyle = depolarizedHere ? "#92f0ff" : "rgba(130, 184, 236, 0.65)";
    ctx.fillText(depolarizedHere ? "+" : "−", x, axonY + 23);
  }

  // 7. Saltatory lightning impulse + orbiting sparks (cyan during spike, golden during recovery).
  if (waveActive) {
    const boltColor = recoveryMode ? "rgba(255, 224, 115, 0.9)" : "rgba(148, 244, 255, 0.95)";
    const auraColor = recoveryMode ? "rgba(255, 206, 86, 0.48)" : "rgba(92, 226, 255, 0.56)";
    const trailStart = Math.max(axonStartX - 10, waveX - 145);

    const pulseAura = ctx.createRadialGradient(waveX, axonY, 4, waveX, axonY, 46);
    pulseAura.addColorStop(0, "#ffffff");
    pulseAura.addColorStop(0.28, auraColor);
    pulseAura.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = pulseAura;
    ctx.beginPath();
    ctx.arc(waveX, axonY, 46, 0, Math.PI * 2);
    ctx.fill();

    drawLightningSegment(
      ctx,
      trailStart,
      axonY,
      waveX,
      axonY,
      sim.elapsedSeconds * 4.5,
      auraColor,
      6.5,
    );
    drawLightningSegment(
      ctx,
      trailStart,
      axonY,
      waveX,
      axonY,
      sim.elapsedSeconds * 4.5,
      boltColor,
      2.2,
    );

    // Highlight active Node(s) of Ranvier with bright electric ring.
    for (const nx of nodeCenters) {
      const dist = Math.abs(nx - waveX);
      if (dist < 62) {
        const strength = 1 - dist / 62;
        ctx.strokeStyle = recoveryMode
          ? `rgba(255, 225, 130, ${0.85 * strength})`
          : `rgba(164, 246, 255, ${0.9 * strength})`;
        ctx.lineWidth = 2.6;
        ctx.beginPath();
        ctx.arc(nx, axonY, 15 + (1 - strength) * 5, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    // Sparkling electric discharge particles around the impulse front.
    if (!recoveryMode) {
      for (let i = 0; i < sim.sparks.length; i += 1) {
        const spark = sim.sparks[i]!;
        const sx = waveX + Math.cos(spark.angle) * (spark.radiusOffset * 1.15);
        const sy = axonY + Math.sin(spark.angle) * (spark.radiusOffset * 0.78);
        ctx.fillStyle = i % 3 === 0 ? "#ffffff" : "#8ae9ff";
        ctx.beginPath();
        ctx.arc(sx, sy, spark.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  // 8. Magnifier focus bracket over middle Node of Ranvier linking down to membrane box.
  const zoomNodeX = nodeCenters[1]!;
  ctx.save();
  ctx.strokeStyle = "rgba(130, 210, 255, 0.5)";
  ctx.lineWidth = 1.2;
  ctx.setLineDash([4, 4]);
  drawRoundRect(ctx, zoomNodeX - 18, axonY - 22, 36, 44, 8);
  ctx.stroke();

  ctx.strokeStyle = "rgba(130, 210, 255, 0.24)";
  ctx.beginPath();
  ctx.moveTo(zoomNodeX - 18, axonY + 22);
  ctx.lineTo(MEMBRANE_BOX.x + 24, MEMBRANE_BOX.y);
  ctx.moveTo(zoomNodeX + 18, axonY + 22);
  ctx.lineTo(MEMBRANE_BOX.x + MEMBRANE_BOX.width - 24, MEMBRANE_BOX.y);
  ctx.stroke();
  ctx.restore();

  // 9. Top-center frosted stage overlay pill matching the video caption banners.
  const banner = PHASE_BANNERS[sim.phase];
  const pillW = 368;
  const pillH = 38;
  const pillX = (AP_WIDTH - pillW) / 2;
  const pillY = 12;

  ctx.fillStyle = "rgba(7, 17, 34, 0.82)";
  ctx.strokeStyle = "rgba(148, 212, 255, 0.34)";
  ctx.lineWidth = 1;
  drawRoundRect(ctx, pillX, pillY, pillW, pillH, 19);
  ctx.fill();
  ctx.stroke();

  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = banner.accent;
  ctx.font = '700 10.5px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.fillText(banner.title, AP_WIDTH / 2, pillY + 12.5);

  ctx.fillStyle = "#eef6ff";
  ctx.font = '500 11px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.fillText(banner.subtitle, AP_WIDTH / 2, pillY + 27);

  ctx.restore();
}

function drawChannelProtein(
  ctx: CanvasRenderingContext2D,
  cx: number,
  openAmount: number,
  inactivatedAmount: number,
  kind: "na" | "k",
): void {
  const gap = 3 + openAmount * 9;
  const subW = 11.5;
  const subH = MEMBRANE_HALF_THICK * 2 + 12;
  const topY = MEMBRANE_MID_Y - subH / 2;

  const isOpenGlow = openAmount > 0.28 && inactivatedAmount < 0.55;
  if (isOpenGlow) {
    const poreGlow = ctx.createRadialGradient(cx, MEMBRANE_MID_Y, 2, cx, MEMBRANE_MID_Y, 26);
    poreGlow.addColorStop(
      0,
      kind === "na" ? "rgba(122, 236, 255, 0.72)" : "rgba(255, 212, 110, 0.68)",
    );
    poreGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = poreGlow;
    ctx.beginPath();
    ctx.arc(cx, MEMBRANE_MID_Y, 26, 0, Math.PI * 2);
    ctx.fill();
  }

  const bodyFill =
    kind === "na" ? (isOpenGlow ? "#5ad3ff" : "#3a7ec2") : isOpenGlow ? "#f6c15a" : "#b8893c";
  const bodyStroke = kind === "na" ? "#b6ecff" : "#ffe6a6";

  ctx.fillStyle = bodyFill;
  ctx.strokeStyle = bodyStroke;
  ctx.lineWidth = 1.25;

  drawRoundRect(ctx, cx - gap / 2 - subW, topY, subW, subH, 5.5);
  ctx.fill();
  ctx.stroke();

  drawRoundRect(ctx, cx + gap / 2, topY, subW, subH, 5.5);
  ctx.fill();
  ctx.stroke();

  // Inactivation gate ball on Na+ channel during peak & repolarization.
  if (kind === "na" && inactivatedAmount > 0.1) {
    const ballY = MEMBRANE_MID_Y + (1 - inactivatedAmount) * 20 + 8;
    ctx.strokeStyle = "rgba(255, 165, 130, 0.85)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx - gap / 2 - 4, topY + subH - 2);
    ctx.quadraticCurveTo(cx - 4, ballY + 6, cx, ballY);
    ctx.stroke();

    ctx.fillStyle = "#ff856d";
    ctx.strokeStyle = "#ffd6cc";
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.arc(cx, ballY, 5.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  // Directional transport chevron when channel is actively conducting.
  if (isOpenGlow) {
    ctx.save();
    ctx.strokeStyle = kind === "na" ? "#fff0a8" : "#c8f7ff";
    ctx.lineWidth = 1.8;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    if (kind === "na") {
      // Downward (inward Na+)
      ctx.beginPath();
      ctx.moveTo(cx, MEMBRANE_MID_Y - 8);
      ctx.lineTo(cx, MEMBRANE_MID_Y + 8);
      ctx.moveTo(cx - 4, MEMBRANE_MID_Y + 4);
      ctx.lineTo(cx, MEMBRANE_MID_Y + 8);
      ctx.lineTo(cx + 4, MEMBRANE_MID_Y + 4);
      ctx.stroke();
    } else {
      // Upward (outward K+)
      ctx.beginPath();
      ctx.moveTo(cx, MEMBRANE_MID_Y + 8);
      ctx.lineTo(cx, MEMBRANE_MID_Y - 8);
      ctx.moveTo(cx - 4, MEMBRANE_MID_Y - 4);
      ctx.lineTo(cx, MEMBRANE_MID_Y - 8);
      ctx.lineTo(cx + 4, MEMBRANE_MID_Y - 4);
      ctx.stroke();
    }
    ctx.restore();
  }

  // Channel label.
  ctx.font = '700 9.5px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = kind === "na" ? "#9ce4ff" : "#ffe099";
  ctx.fillText(kind === "na" ? "Na⁺" : "K⁺", cx, topY - 8);
}

function drawMembraneChamber(ctx: CanvasRenderingContext2D, sim: ActionPotentialSimulation): void {
  const { x, y, width, height } = MEMBRANE_BOX;

  ctx.save();
  drawRoundRect(ctx, x, y, width, height, 14);
  ctx.fillStyle = "rgba(8, 21, 41, 0.9)";
  ctx.fill();
  ctx.strokeStyle = "rgba(126, 194, 255, 0.28)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  ctx.clip();

  // Subtle top/bottom compartment tint.
  const extTint = ctx.createLinearGradient(0, y, 0, MEMBRANE_MID_Y - MEMBRANE_HALF_THICK);
  extTint.addColorStop(0, "rgba(42, 104, 184, 0.14)");
  extTint.addColorStop(1, "rgba(22, 56, 108, 0.04)");
  ctx.fillStyle = extTint;
  ctx.fillRect(x, y, width, MEMBRANE_MID_Y - MEMBRANE_HALF_THICK - y);

  // Phospholipid membrane band across middle.
  const memTop = MEMBRANE_MID_Y - MEMBRANE_HALF_THICK;
  const memH = MEMBRANE_HALF_THICK * 2;
  const memGrad = ctx.createLinearGradient(0, memTop, 0, memTop + memH);
  memGrad.addColorStop(0, "rgba(116, 188, 255, 0.34)");
  memGrad.addColorStop(0.5, "rgba(54, 108, 174, 0.26)");
  memGrad.addColorStop(1, "rgba(116, 188, 255, 0.34)");
  ctx.fillStyle = memGrad;
  ctx.fillRect(x, memTop, width, memH);

  // Schematic bilayer head dots along the membrane outside channels.
  ctx.fillStyle = "rgba(156, 214, 255, 0.45)";
  for (let hx = x + 10; hx <= x + width - 10; hx += 10) {
    const nearChannel =
      NA_CHANNEL_X.some((cx) => Math.abs(hx - cx) < 20) ||
      K_CHANNEL_X.some((cx) => Math.abs(hx - cx) < 20);
    if (nearChannel) continue;
    ctx.beginPath();
    ctx.arc(hx, memTop + 2.5, 2.2, 0, Math.PI * 2);
    ctx.arc(hx, memTop + memH - 2.5, 2.2, 0, Math.PI * 2);
    ctx.fill();
  }

  // Compartment labels.
  ctx.font = '600 10px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  ctx.fillStyle = "rgba(182, 222, 255, 0.86)";
  ctx.fillText("Extracellular (high Na⁺)", x + 12, y + 9);

  ctx.textBaseline = "bottom";
  ctx.fillStyle = "rgba(166, 214, 255, 0.86)";
  ctx.fillText("Intracellular axoplasm (high K⁺)", x + 12, y + height - 9);

  // Membrane polarity indicators along surfaces.
  const flipped = sim.phase === "depolarization" || sim.phase === "peak";
  const hyper = sim.phase === "hyperpolarization";
  ctx.font = '700 11px ui-monospace, "SF Mono", Menlo, monospace';
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  for (let px = x + 36; px <= x + width - 30; px += 46) {
    const nearCh =
      NA_CHANNEL_X.some((cx) => Math.abs(px - cx) < 22) ||
      K_CHANNEL_X.some((cx) => Math.abs(px - cx) < 22);
    if (nearCh) continue;

    ctx.fillStyle = flipped ? "#ffe07d" : "rgba(170, 224, 255, 0.65)";
    ctx.fillText(flipped ? "−" : "+", px, memTop - 9);

    ctx.fillStyle = flipped ? "#88ecff" : hyper ? "#c6baff" : "rgba(148, 200, 248, 0.65)";
    ctx.fillText(flipped ? "+" : hyper ? "−−" : "−", px, memTop + memH + 10);
  }

  // Voltage-gated channels.
  for (const cx of NA_CHANNEL_X) {
    drawChannelProtein(ctx, cx, sim.naOpen, sim.naInactivated, "na");
  }
  for (const cx of K_CHANNEL_X) {
    drawChannelProtein(ctx, cx, sim.kOpen, 0, "k");
  }

  // Conserved Na+ (golden) and K+ (pale cyan) ion particles.
  for (let i = 0; i < sim.ions.length; i += 1) {
    const ion = sim.ions[i]!;
    const isNa = ion.kind === "na";
    const radius = isNa ? 4.3 : 4.1;

    // Velocity streak when actively streaming through an open pore.
    if (Math.abs(ion.vy) > 48 && Math.abs(ion.y - MEMBRANE_MID_Y) < 58) {
      ctx.strokeStyle = isNa ? "rgba(255, 224, 112, 0.55)" : "rgba(148, 240, 255, 0.55)";
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(ion.x, ion.y);
      ctx.lineTo(ion.x - ion.vx * 0.08, ion.y - ion.vy * 0.1);
      ctx.stroke();
    }

    const sprite = getIonSprite(isNa);
    if (sprite) {
      ctx.drawImage(
        sprite.canvas,
        ion.x - sprite.halfSize,
        ion.y - sprite.halfSize,
        sprite.logicalSize,
        sprite.logicalSize,
      );
    } else {
      const grad = ctx.createRadialGradient(ion.x - 1.3, ion.y - 1.3, 0.5, ion.x, ion.y, radius);
      if (isNa) {
        grad.addColorStop(0, "#fff8cf");
        grad.addColorStop(0.55, "#ffd54f");
        grad.addColorStop(1, "#cc8414");
      } else {
        grad.addColorStop(0, "#f2fdff");
        grad.addColorStop(0.55, "#83e2ff");
        grad.addColorStop(1, "#2a8bc7");
      }

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(ion.x, ion.y, radius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.restore();
}

function drawOscilloscope(ctx: CanvasRenderingContext2D, sim: ActionPotentialSimulation): void {
  const boxX = 518;
  const boxY = 238;
  const boxW = 246;
  const boxH = 228;

  ctx.save();
  drawRoundRect(ctx, boxX, boxY, boxW, boxH, 14);
  ctx.fillStyle = "rgba(8, 21, 41, 0.9)";
  ctx.fill();
  ctx.strokeStyle = "rgba(126, 194, 255, 0.28)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Header label & live mV badge.
  ctx.font = '600 10px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.fillStyle = "rgba(198, 228, 255, 0.9)";
  ctx.fillText("Membrane potential (mV)", boxX + 12, boxY + 18);

  const mvText = `${sim.voltageMv > 0 ? "+" : ""}${sim.voltageMv} mV`;
  const banner = PHASE_BANNERS[sim.phase];
  ctx.textAlign = "right";
  ctx.fillStyle = banner.accent;
  ctx.font = '700 11px ui-monospace, "SF Mono", Menlo, monospace';
  ctx.fillText(mvText, boxX + boxW - 12, boxY + 18);

  // Plot region.
  const px = boxX + 38;
  const py = boxY + 38;
  const pw = boxW - 50;
  const ph = boxH - 64;

  const mvToY = (mv: number) => {
    const minMv = -90;
    const maxMv = 42;
    const norm = (mv - minMv) / (maxMv - minMv);
    return py + ph - norm * ph;
  };
  const tToX = (t: number) => px + (t / CYCLE_DURATION_SECONDS) * pw;

  // Horizontal voltage reference lines.
  const refs = [
    { mv: 30, label: "+30", dash: false, color: "rgba(136, 200, 255, 0.16)" },
    { mv: 0, label: "0", dash: false, color: "rgba(136, 200, 255, 0.22)" },
    { mv: THRESHOLD_MV, label: "−55", dash: true, color: "rgba(255, 204, 102, 0.42)" },
    { mv: RESTING_MV, label: "−70", dash: true, color: "rgba(116, 210, 255, 0.4)" },
    { mv: -80, label: "−80", dash: false, color: "rgba(136, 200, 255, 0.16)" },
  ];

  ctx.font = '500 9px ui-monospace, "SF Mono", Menlo, monospace';
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  for (const ref of refs) {
    const ry = mvToY(ref.mv);
    ctx.save();
    ctx.strokeStyle = ref.color;
    ctx.lineWidth = 1;
    if (ref.dash) ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(px, ry);
    ctx.lineTo(px + pw, ry);
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = "rgba(176, 212, 246, 0.78)";
    ctx.fillText(ref.label, px - 6, ry);
  }

  // Faint full reference waveform.
  ctx.strokeStyle = "rgba(134, 198, 255, 0.24)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  const samples = 120;
  for (let i = 0; i <= samples; i += 1) {
    const t = (i / samples) * CYCLE_DURATION_SECONDS;
    const vx = tToX(t);
    const vy = mvToY(voltageAtCycleTime(t));
    if (i === 0) ctx.moveTo(vx, vy);
    else ctx.lineTo(vx, vy);
  }
  ctx.stroke();

  // Active illuminated waveform up to current cycleTime.
  const activeSamples = Math.max(1, Math.round((sim.cycleTime / CYCLE_DURATION_SECONDS) * samples));
  ctx.strokeStyle = banner.accent;
  ctx.lineWidth = 2.6;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  for (let i = 0; i <= activeSamples; i += 1) {
    const t = Math.min(sim.cycleTime, (i / samples) * CYCLE_DURATION_SECONDS);
    const vx = tToX(t);
    const vy = mvToY(voltageAtCycleTime(t));
    if (i === 0) ctx.moveTo(vx, vy);
    else ctx.lineTo(vx, vy);
  }
  ctx.stroke();

  // Live cursor dot.
  const curX = tToX(sim.cycleTime);
  const curY = mvToY(voltageAtCycleTime(sim.cycleTime));
  const dotGlow = ctx.createRadialGradient(curX, curY, 1, curX, curY, 12);
  dotGlow.addColorStop(0, "#ffffff");
  dotGlow.addColorStop(0.4, banner.accent);
  dotGlow.addColorStop(1, "rgba(0, 0, 0, 0)");
  ctx.fillStyle = dotGlow;
  ctx.beginPath();
  ctx.arc(curX, curY, 12, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(curX, curY, 3.6, 0, Math.PI * 2);
  ctx.fill();

  // Bottom axis caption.
  ctx.textAlign = "center";
  ctx.textBaseline = "bottom";
  ctx.fillStyle = "rgba(154, 198, 240, 0.72)";
  ctx.font = '500 9.5px -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif';
  ctx.fillText("Time across impulse cycle", px + pw / 2, boxY + boxH - 8);

  ctx.restore();
}

export function renderActionPotentialFrame(
  ctx: CanvasRenderingContext2D,
  sim: ActionPotentialSimulation,
  cssWidth: number,
  cssHeight: number,
): void {
  const dpr = ctx.getTransform().a || 1;
  const targetWidth = Math.max(1, Math.round(cssWidth * dpr));
  const targetHeight = Math.max(1, Math.round(cssHeight * dpr));
  const scaleX = cssWidth / AP_WIDTH;
  const scaleY = cssHeight / AP_HEIGHT;

  ctx.save();
  ctx.scale(scaleX, scaleY);

  if (!paintCachedBackground(ctx, targetWidth, targetHeight)) {
    drawBackground(ctx);
  }
  drawWholeNeuronScene(ctx, sim);
  drawMembraneChamber(ctx, sim);
  drawOscilloscope(ctx, sim);

  ctx.restore();
}
